import fs from 'node:fs';

// Order is deliberate: preserve the established responsive and component cascade.
export const styleFiles = [
  'tokens.css',
  'foundation.css',
  'layout.css',
  'components.css',
  'evidence.css',
  'interaction.css',
];
export function compileStyles() {
  return (
    '/* Generated by npm run prepare:styles. Edit styles/*.css, not this file. */\n' +
    styleFiles
      .map(
        (name) =>
          `\n/* ${name} */\n` +
          fs.readFileSync(new URL('../../styles/' + name, import.meta.url), 'utf8'),
      )
      .join('')
  );
}
